Definition mk_0RB0LC_1LC1RB_1RD1LA_1RB0LB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LC_1LC1RB_1RD1LA_1RB0LB.

(** 0RB0LC_1LC1RB_1RD1LA_1RB0LB *)
(** 0RB0LC_1LC1RB_1RD1LA_1RB0LB -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_1RD1LA_1RB0LB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StB end.

(** Its mirror 0LB0RC_1RC1LB_1LD1RA_1LB0RB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_1RD1LA_1RB0LB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_1RD1LA_1RB0LB : list Instr := [(StD, S1)].
Definition tmw_0RB0LC_1LC1RB_1RD1LA_1RB0LB : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_1RD1LA_1RB0LB pins_0RB0LC_1LC1RB_1RD1LA_1RB0LB.
Local Notation tm := tmw_0RB0LC_1LC1RB_1RD1LA_1RB0LB.

Lemma mirror_ok_0RB0LC_1LC1RB_1RD1LA_1RB0LB : mirror_tm tm_0RB0LC_1LC1RB_1RD1LA_1RB0LB = tmm_0RB0LC_1LC1RB_1RD1LA_1RB0LB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RB_1RD1LA_1RB0LB (p : positive) : cconf := (StA, (Ap_Alph_10_11_11 p ++ [S1;S1;S0], S0, [])).
