Lemma run_int_0RB0LC_1LC1RB_1RD1LA_1RB0LB : srun tm false true chi_0RB0LC_1LC1RB_1RD1LA_1RB0LB A0_0RB0LC_1LC1RB_1RD1LA_1RB0LB = Some (A1_0RB0LC_1LC1RB_1RD1LA_1RB0LB, 4, 4).
