Definition B0_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [] [S1;S1] 1 1 [S1;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [] [S1;S0] 1 2 [S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StA *)
Definition Cin_0RB0LC_1LC1RB_1RD1LA_1RB0LB (v : positive) : cconf := (StA, (Ip v ++ [S0;S1;S1], S0, [])).
