(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RB_1RD1LA_1RB0LB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_1RD1LA_1RB0LB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_0RB0LC_1LC1RB_1RD1LA_1RB0LB : srun tm false true chn_0RB0LC_1LC1RB_1RD1LA_1RB0LB AI0_0RB0LC_1LC1RB_1RD1LA_1RB0LB = Some (AI1_0RB0LC_1LC1RB_1RD1LA_1RB0LB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** The OFFSET start: [E (2^(n+2)+2)] is fixed digit blocks, then the rep.
    Its block count is one short of the outer index, which is why [lapo_]
    below REINDEXES at [j = S j']. *)
Lemma epre_0RB0LC_1LC1RB_1RD1LA_1RB0LB : forall n, Ip (xO (xI (pow2 n))) = [S1;S0;S1;S1] ++ rep [S1;S0] n ++ [S1].
Proof.
  intro n. cbn [Ip]. rewrite epow2_0RB0LC_1LC1RB_1RD1LA_1RB0LB.
  cbn [app]. rewrite <- ?app_assoc. cbn [app]. reflexivity.
Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [S1;S0;S1;S1] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB0LC_1LC1RB_1RD1LA_1RB0LB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2; SRotL 1; SWin 1; SRotL 1; SWin 4; SWinR 1].

Lemma run_boot_0RB0LC_1LC1RB_1RD1LA_1RB0LB : srun tm true true chb_0RB0LC_1LC1RB_1RD1LA_1RB0LB B0_0RB0LC_1LC1RB_1RD1LA_1RB0LB = Some (BB1_0RB0LC_1LC1RB_1RD1LA_1RB0LB, 4, 21).
