(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_1RD1LA_1RB0LB : sconf := mkC StA (mkS [] [S1;S1] 1 2 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LC_1LC1RB_1RD1LA_1RB0LB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_exit_0RB0LC_1LC1RB_1RD1LA_1RB0LB : srun tm true true che_0RB0LC_1LC1RB_1RD1LA_1RB0LB BE0_0RB0LC_1LC1RB_1RD1LA_1RB0LB = Some (B1_0RB0LC_1LC1RB_1RD1LA_1RB0LB, 4, 12).
