(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_1RD1LA_1RB0LC : forall t, ~ In t pins_0RB0LC_1LC1RB_1RD1LA_1RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_A0_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_A1_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 6] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B0_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B1_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C0_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C1_0RB0LC_1LC1RB_1RD1LA_1RB0LC.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
