(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_0RB0LC_1LC1RB_1RD1LA_1RB0LD : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB0LD) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB0LD = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1RD1LA_1RB0LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB0LD. rewrite epre_0RB0LC_1LC1RB_1RD1LA_1RB0LD.
    first [ rewrite <- ?app_assoc; reflexivity
