(** [cview p = (1, None)] forces [p = 1], where the offset family's count is
    empty: the overflow lap at p = 1 is ONE CONCRETE run, checked the way the
    bootstrap lemma is. *)
Lemma lapo0_0RB0LC_1LC1RB_1RD1LA_1RB0RC : exists n c', csteps tm n (Cc 1) = Some c'
    /\ lift c' = lift (Cc 2) /\ 0 < n.
Proof.
  exists 17.
  assert (H : match csteps tm 17 (Cc 1) with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 (Cc 1)) as [c|] eqn:E0; [|discriminate].
  exists c. split; [reflexivity|]. split; [apply ceqb_lift; exact H | lia].
Qed.

(** The outer OVERFLOW branch.  The offset family's block count is one short
    of the outer index, so the branch REINDEXES: the generic route runs at
    [j = S j'] and [j = 0] is the concrete lap above. *)
Lemma lapo_0RB0LC_1LC1RB_1RD1LA_1RB0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  destruct j as [|j'].
  - rewrite (cview_none_shape p 0 E). exact lapo0_0RB0LC_1LC1RB_1RD1LA_1RB0RC.
  - apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1RD1LA_1RB0RC p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_0RB0LC_1LC1RB_1RD1LA_1RB0RC).
      split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1RD1LA_1RB0RC j')].
      rewrite (gso_0RB0LC_1LC1RB_1RD1LA_1RB0RC p j' E).
      exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1RD1LA_1RB0RC B0_0RB0LC_1LC1RB_1RD1LA_1RB0RC BB1_0RB0LC_1LC1RB_1RD1LA_1RB0RC 4 21
               run_boot_0RB0LC_1LC1RB_1RD1LA_1RB0RC [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_0RB0LC_1LC1RB_1RD1LA_1RB0RC).
      split; [| exact (geo_0RB0LC_1LC1RB_1RD1LA_1RB0RC p j' E)].
      rewrite (gxi_0RB0LC_1LC1RB_1RD1LA_1RB0RC j').
      exact (srun_sound tm true true che_0RB0LC_1LC1RB_1RD1LA_1RB0RC BE0_0RB0LC_1LC1RB_1RD1LA_1RB0RC B1_0RB0LC_1LC1RB_1RD1LA_1RB0RC 4 12
               run_exit_0RB0LC_1LC1RB_1RD1LA_1RB0RC [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
Qed.

