  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_1RD1LA_1RB0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_1RD1LA_1RB0RC p j E)].
Qed.


