  rewrite (gsi_0RB0LC_1LC1RB_1RD1LA_1RB1LB p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0LC_1LC1RB_1RD1LA_1RB1LB A0_0RB0LC_1LC1RB_1RD1LA_1RB1LB A1_0RB0LC_1LC1RB_1RD1LA_1RB1LB 4 4
             run_int_0RB0LC_1LC1RB_1RD1LA_1RB1LB (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0LC_1LC1RB_1RD1LA_1RB1LB p j q0 E).
Qed.

Lemma gso_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall p j, cview p = (S (S j), None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_1RD1LA_1RB1LB.
Proof.
