Lemma lapin_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_0RB0LC_1LC1RB_1RD1LA_1RB1LB).
  split; [lia|]. split; [| exact (gen_0RB0LC_1LC1RB_1RD1LA_1RB1LB v i q0 E)].
  rewrite (gsn_0RB0LC_1LC1RB_1RD1LA_1RB1LB v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_1RD1LA_1RB1LB AI0_0RB0LC_1LC1RB_1RD1LA_1RB1LB AI1_0RB0LC_1LC1RB_1RD1LA_1RB1LB 4 4
           run_inner_0RB0LC_1LC1RB_1RD1LA_1RB1LB (Ip q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB1LB) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB1LB = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1RD1LA_1RB1LB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1LB. rewrite epre_0RB0LC_1LC1RB_1RD1LA_1RB1LB.
    first [ rewrite <- ?app_assoc; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  (* The offset boot can land one written blank past the anchor on EITHER
     side, and [lift] sees neither.  Strip it FIRST: [cbn [app]] flattens
     `w ++ [S0]` into one literal and destroys the shape
     [WTape.lift_app_blank_l] matches on. *)
  rewrite HD, HC. rewrite ?lift_app_blank_l.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?lbl_0RB0LC_1LC1RB_1RD1LA_1RB1LB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** The offset family's all-ones fill is the ordinary one two octaves up:
    [fill (xO (xI (pow2 j))) = fill (pow2 (S (S j)))] by computation, so
    [cview_fill_pow2] still names the exit chain's start word. *)
Lemma gxi_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall j, Cin (fill (xO (xI (pow2 j)))) = cden [] [] j BE0_0RB0LC_1LC1RB_1RD1LA_1RB1LB.
Proof.
  intro j.
  assert (Hf : fill (xO (xI (pow2 j))) = fill (pow2 (S (S j))))
    by (cbn [pow2 fill]; reflexivity).
  rewrite Hf.
  destruct (ILCounter.cview_none_I (fill (pow2 (S (S j)))) (S (S j))
              (cview_fill_pow2 (S (S j)))) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1LB, cden, BE0_0RB0LC_1LC1RB_1RD1LA_1RB1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 2) with (S (S j)) by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_1RD1LA_1RB1LB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** [cview p = (1, None)] forces [p = 1], where the offset family's count is
    empty: the overflow lap at p = 1 is ONE CONCRETE run, checked the way the
    bootstrap lemma is. *)
Lemma lapo0_0RB0LC_1LC1RB_1RD1LA_1RB1LB : exists n c', csteps tm n (Cc 1) = Some c'
    /\ lift c' = lift (Cc 2) /\ 0 < n.
Proof.
  exists 17.
  assert (H : match csteps tm 17 (Cc 1) with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 (Cc 1)) as [c|] eqn:E0; [|discriminate].
  exists c. split; [reflexivity|]. split; [apply ceqb_lift; exact H | lia].
Qed.

(** The outer OVERFLOW branch.  The offset family's block count is one short
    of the outer index, so the branch REINDEXES: the generic route runs at
    [j = S j'] and [j = 0] is the concrete lap above. *)
Lemma lapo_0RB0LC_1LC1RB_1RD1LA_1RB1LB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  destruct j as [|j'].
  - rewrite (cview_none_shape p 0 E). exact lapo0_0RB0LC_1LC1RB_1RD1LA_1RB1LB.
  - apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1RD1LA_1RB1LB p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_0RB0LC_1LC1RB_1RD1LA_1RB1LB).
      split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1RD1LA_1RB1LB j')].
      rewrite (gso_0RB0LC_1LC1RB_1RD1LA_1RB1LB p j' E).
      exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1RD1LA_1RB1LB B0_0RB0LC_1LC1RB_1RD1LA_1RB1LB BB1_0RB0LC_1LC1RB_1RD1LA_1RB1LB 4 21
               run_boot_0RB0LC_1LC1RB_1RD1LA_1RB1LB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_0RB0LC_1LC1RB_1RD1LA_1RB1LB).
      split; [| exact (geo_0RB0LC_1LC1RB_1RD1LA_1RB1LB p j' E)].
      rewrite (gxi_0RB0LC_1LC1RB_1RD1LA_1RB1LB j').
      exact (srun_sound tm true true che_0RB0LC_1LC1RB_1RD1LA_1RB1LB BE0_0RB0LC_1LC1RB_1RD1LA_1RB1LB B1_0RB0LC_1LC1RB_1RD1LA_1RB1LB 4 12
               run_exit_0RB0LC_1LC1RB_1RD1LA_1RB1LB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
Qed.

