    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
