Definition A0_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chi_0RB0LC_1LC1RB_1RD1LA_1RB1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_0RB0LC_1LC1RB_1RD1LA_1RB1RB : srun tm false true chi_0RB0LC_1LC1RB_1RD1LA_1RB1RB A0_0RB0LC_1LC1RB_1RD1LA_1RB1RB = Some (A1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S1] 1 1 [S1;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S0] 1 2 [S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StA *)
Definition Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB (v : positive) : cconf := (StA, (Ip v ++ [S0;S1;S1], S0, [])).
Local Notation Cin := Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_1RD1LA_1RB1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_0RB0LC_1LC1RB_1RD1LA_1RB1RB : srun tm false true chn_0RB0LC_1LC1RB_1RD1LA_1RB1RB AI0_0RB0LC_1LC1RB_1RD1LA_1RB1RB = Some (AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** The OFFSET start: [E (2^(n+2)+2)] is fixed digit blocks, then the rep.
    Its block count is one short of the outer index, which is why [lapo_]
    below REINDEXES at [j = S j']. *)
Lemma epre_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall n, Ip (xO (xI (pow2 n))) = [S1;S0;S1;S1] ++ rep [S1;S0] n ++ [S1].
Proof.
  intro n. cbn [Ip]. rewrite epow2_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
  cbn [app]. rewrite <- ?app_assoc. cbn [app]. reflexivity.
Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [S1;S0;S1;S1] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB0LC_1LC1RB_1RD1LA_1RB1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2; SRotL 1; SWin 1; SRotL 1; SWin 4; SWinR 1].

Lemma run_boot_0RB0LC_1LC1RB_1RD1LA_1RB1RB : srun tm true true chb_0RB0LC_1LC1RB_1RD1LA_1RB1RB B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB = Some (BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, 4, 21).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_1RD1LA_1RB1RB : sconf := mkC StA (mkS [] [S1;S1] 1 2 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LC_1LC1RB_1RD1LA_1RB1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_exit_0RB0LC_1LC1RB_1RD1LA_1RB1RB : srun tm true true che_0RB0LC_1LC1RB_1RD1LA_1RB1RB BE0_0RB0LC_1LC1RB_1RD1LA_1RB1RB = Some (B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j A0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, A0_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j A1_0RB0LC_1LC1RB_1RD1LA_1RB1RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, A1_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0LC_1LC1RB_1RD1LA_1RB1RB A0_0RB0LC_1LC1RB_1RD1LA_1RB1RB A1_0RB0LC_1LC1RB_1RD1LA_1RB1RB 4 4
             run_int_0RB0LC_1LC1RB_1RD1LA_1RB1RB (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j q0 E).
Qed.

Lemma gso_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j, cview p = (S (S j), None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with ((S j)) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j, cview p = (S (S j), None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB
             = (StA, (rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1], S0, []))).
  { unfold cden, B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 2) with (S (S j)) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LC_1LC1RB_1RD1LA_1RB1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LC_1LC1RB_1RD1LA_1RB1RB. reflexivity.
Qed.

Lemma gsn_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] i AI0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, AI0_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB).
  split; [lia|]. split; [| exact (gen_0RB0LC_1LC1RB_1RD1LA_1RB1RB v i q0 E)].
  rewrite (gsn_0RB0LC_1LC1RB_1RD1LA_1RB1RB v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_1RD1LA_1RB1RB AI0_0RB0LC_1LC1RB_1RD1LA_1RB1RB AI1_0RB0LC_1LC1RB_1RD1LA_1RB1RB 4 4
           run_inner_0RB0LC_1LC1RB_1RD1LA_1RB1RB (Ip q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StA, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB. rewrite epre_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    first [ rewrite <- ?app_assoc; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  (* The offset boot can land one written blank past the anchor on EITHER
     side, and [lift] sees neither.  Strip it FIRST: [cbn [app]] flattens
     `w ++ [S0]` into one literal and destroys the shape
     [WTape.lift_app_blank_l] matches on. *)
  rewrite HD, HC. rewrite ?lift_app_blank_l.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?lbl_0RB0LC_1LC1RB_1RD1LA_1RB1RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** The offset family's all-ones fill is the ordinary one two octaves up:
    [fill (xO (xI (pow2 j))) = fill (pow2 (S (S j)))] by computation, so
    [cview_fill_pow2] still names the exit chain's start word. *)
Lemma gxi_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall j, Cin (fill (xO (xI (pow2 j)))) = cden [] [] j BE0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
Proof.
  intro j.
  assert (Hf : fill (xO (xI (pow2 j))) = fill (pow2 (S (S j))))
    by (cbn [pow2 fill]; reflexivity).
  rewrite Hf.
  destruct (ILCounter.cview_none_I (fill (pow2 (S (S j)))) (S (S j))
              (cview_fill_pow2 (S (S j)))) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1RD1LA_1RB1RB, cden, BE0_0RB0LC_1LC1RB_1RD1LA_1RB1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 2) with (S (S j)) by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** [cview p = (1, None)] forces [p = 1], where the offset family's count is
    empty: the overflow lap at p = 1 is ONE CONCRETE run, checked the way the
    bootstrap lemma is. *)
Lemma lapo0_0RB0LC_1LC1RB_1RD1LA_1RB1RB : exists n c', csteps tm n (Cc 1) = Some c'
    /\ lift c' = lift (Cc 2) /\ 0 < n.
Proof.
  exists 17.
  assert (H : match csteps tm 17 (Cc 1) with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 (Cc 1)) as [c|] eqn:E0; [|discriminate].
  exists c. split; [reflexivity|]. split; [apply ceqb_lift; exact H | lia].
Qed.

(** The outer OVERFLOW branch.  The offset family's block count is one short
    of the outer index, so the branch REINDEXES: the generic route runs at
    [j = S j'] and [j = 0] is the concrete lap above. *)
Lemma lapo_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  destruct j as [|j'].
  - rewrite (cview_none_shape p 0 E). exact lapo0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
  - apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1RD1LA_1RB1RB p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB).
      split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1RD1LA_1RB1RB j')].
      rewrite (gso_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j' E).
      exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1RD1LA_1RB1RB B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB BB1_0RB0LC_1LC1RB_1RD1LA_1RB1RB 4 21
               run_boot_0RB0LC_1LC1RB_1RD1LA_1RB1RB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB).
      split; [| exact (geo_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j' E)].
      rewrite (gxi_0RB0LC_1LC1RB_1RD1LA_1RB1RB j').
      exact (srun_sound tm true true che_0RB0LC_1LC1RB_1RD1LA_1RB1RB BE0_0RB0LC_1LC1RB_1RD1LA_1RB1RB B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB 4 12
               run_exit_0RB0LC_1LC1RB_1RD1LA_1RB1RB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** State StA's visit witness at the reindex's p = 1 case -- concrete. *)
Lemma visz_StA_0RB0LC_1LC1RB_1RD1LA_1RB1RB : exists k c, csteps tm k (Cc 1) = Some c /\ fst c = StA.
Proof. exists 0. eexists. split; [vm_compute; reflexivity | reflexivity]. Qed.

(** State StB's visit witness at the reindex's p = 1 case -- concrete. *)
Lemma visz_StB_0RB0LC_1LC1RB_1RD1LA_1RB1RB : exists k c, csteps tm k (Cc 1) = Some c /\ fst c = StB.
Proof. exists 1. eexists. split; [vm_compute; reflexivity | reflexivity]. Qed.

(** State StC's visit witness at the reindex's p = 1 case -- concrete. *)
Lemma visz_StC_0RB0LC_1LC1RB_1RD1LA_1RB1RB : exists k c, csteps tm k (Cc 1) = Some c /\ fst c = StC.
Proof. exists 6. eexists. split; [vm_compute; reflexivity | reflexivity]. Qed.

(** State StD's visit witness at the reindex's p = 1 case -- concrete. *)
Lemma visz_StD_0RB0LC_1LC1RB_1RD1LA_1RB1RB : exists k c, csteps tm k (Cc 1) = Some c /\ fst c = StD.
Proof. exists 11. eexists. split; [vm_compute; reflexivity | reflexivity]. Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1RD1LA_1RB1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_1RD1LA_1RB1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1LC1RB_1RD1LA_1RB1RB : stepn tmm_0RB0LC_1LC1RB_1RD1LA_1RB1RB 23 InitES = Some (lift (Cc 2)).
Proof.
  assert (H : match csteps tmm_0RB0LC_1LC1RB_1RD1LA_1RB1RB 23 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LC_1LC1RB_1RD1LA_1RB1RB 23 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LC_1LC1RB_1RD1LA_1RB1RB : existsb (fun tg => cfires tmm_0RB0LC_1LC1RB_1RD1LA_1RB1RB c0 23 tg) pins_0RB0LC_1LC1RB_1RD1LA_1RB1RB = true.
