    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 6] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B1_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C0 *)
