    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C1_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_D0_0RB0LC_1LC1RB_1RD1LA_1RB1RB.
    + exact (fireo_0RB0LC_1LC1RB_1RD1LA_1RB1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D1: pinned *)
