    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1LC1RA_1RD1LB_0LC0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1LC1RA_1RD1LB_0LC0RD = Some t ->
