Lemma fireo_0RB0RC_1RC0LA_1LD1RB_0RC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RC_1RC0LA_1LD1RB_0RC0LD = Some t ->
