(** 1RB0LB_1LC1RA_0RB0LC_------ *)
(** 1RB0LB_1LC1RA_0RB0LC_------ -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LB_1LC1RA_0RB0LC_______ : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
  | StD, S0 => None | StD, S1 => None end.

(** Its mirror 1LB0RB_1RC1LA_0LB0RC_------: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LB_1LC1RA_0RB0LC_______ : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StC
  | StD, S0 => None | StD, S1 => None end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LB_1LC1RA_0RB0LC_______ : list Instr := [(StD, S0); (StD, S1); (StA, S1)].
Definition tmw_1RB0LB_1LC1RA_0RB0LC_______ : TM := tm_wrap_trs tmm_1RB0LB_1LC1RA_0RB0LC_______ pins_1RB0LB_1LC1RA_0RB0LC_______.
Local Notation tm := tmw_1RB0LB_1LC1RA_0RB0LC_______.

Lemma mirror_ok_1RB0LB_1LC1RA_0RB0LC_______ : mirror_tm tm_1RB0LB_1LC1RA_0RB0LC_______ = tmm_1RB0LB_1LC1RA_0RB0LC_______.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LB_1LC1RA_0RB0LC_______ (p : positive) : cconf := (StC, (Ap_Alph_00_10_1 p ++ [S0], S0, [])).
