Definition chp_1RB0LB_1LC1RA_0RB0LC_______ : list lstep := [SWin 2; SCycL 2 0; SWin 2; SCycR 2; SWin 2].

Lemma run_p_1RB0LB_1LC1RA_0RB0LC_______ : srun tm false true chp_1RB0LB_1LC1RA_0RB0LC_______ P0_1RB0LB_1LC1RA_0RB0LC_______ = Some (P1_1RB0LB_1LC1RA_0RB0LC_______, 4, 6).
