Definition B0_1RB0LB_1LC1RA_0RB0LC_______ : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LB_1LC1RA_0RB0LC_______ : sconf := mkC StC (mkS [] [S0;S0] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
Definition cho_1RB0LB_1LC1RA_0RB0LC_______ : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_ovf_1RB0LB_1LC1RA_0RB0LC_______ : srun tm true true cho_1RB0LB_1LC1RA_0RB0LC_______ B0_1RB0LB_1LC1RA_0RB0LC_______ = Some (B1_1RB0LB_1LC1RA_0RB0LC_______, 4, 6).
